import { describe, it, expect } from "vitest";
import {
  OFFLINE_MAGIC,
  COUNTER_BASE,
  RELIABILITY,
  parseUdmuxFrame,
  buildUdmuxFrame,
  nonceOf,
  counterFromHint,
  aeadSeal,
  aeadOpen,
  parseDatagram,
  buildDatagram,
  buildMessage,
  SplitAssembler,
  buildUnconnectedPing,
  parseUnconnectedPong,
} from "../src/transport/raknet-codec.js";

const hex = (s) => Buffer.from(s, "hex");

// Reference vectors generated by the Python reference implementation
// (rbxraknet framing.py / RakNet dissector field layout).
const UDMUX_1F =
  "0100001f011102000102030405060708090a0b0c0d0e0f0001020304050607" +
  "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa" +
  "aa3412bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
const DATAGRAM = "800302016000080c0b0a33221105aa";
const ACK = "c000020101000000050000090000";
const NAK = "a0000101020000";
const SPLITMSG = "5000100706050000000312340000000161626364";
const PING =
  "01112233445566778800ffff00fefefefefdfdfdfd123456780102030405060708";
const PONG =
  "1c1122334455667788aabbccddeeff001100ffff00fefefefefdfdfdfd1234567800044d4f5444";

describe("UDMUX framing", () => {
  it("parses a measured 0x1f datagram", () => {
    const frame = parseUdmuxFrame(hex(UDMUX_1F));
    expect(frame.direction).toBe(0x1f);
    expect(frame.epochTag.toString("hex")).toBe("000102030405060708090a0b0c0d0e0f");
    expect(frame.mux.toString("hex")).toBe("0001020304050607");
    expect(frame.ciphertext.length).toBe(40);
    expect(frame.counterHint).toBe(0x1234);
    expect(frame.tag.length).toBe(16);
  });

  it("rebuilds the exact measured bytes", () => {
    const frame = parseUdmuxFrame(hex(UDMUX_1F));
    expect(buildUdmuxFrame(frame).toString("hex")).toBe(UDMUX_1F);
  });

  it("rejects payloads that are not UDMUX framed", () => {
    expect(() => parseUdmuxFrame(Buffer.from([0x02, 0, 0, 0x1f]))).toThrow(/UDMUX/i);
    expect(() => parseUdmuxFrame(Buffer.from([0x01, 0, 0, 0x19]))).toThrow(/header/i);
  });
});

describe("nonce law", () => {
  it("spells UniqueNumbeR at the base counter", () => {
    expect(nonceOf(COUNTER_BASE).toString("hex")).toBe("556e697175654e756d626552");
    expect(nonceOf(COUNTER_BASE).toString("ascii")).toBe("UniqueNumbeR");
  });

  it("increments the low byte first", () => {
    expect(nonceOf(COUNTER_BASE + 1n).toString("hex")).toBe("566e697175654e756d626552");
  });

  it("rebuilds a wrapped counter hint from the last seen value", () => {
    expect(counterFromHint(0x0010, 0x0000_0010n)).toBe(0x0000_0010n);
    expect(counterFromHint(0x0000, 0x0000_ffffn)).toBe(0x0001_0000n);
    expect(counterFromHint(0xffff, 0x0001_0000n)).toBe(0x0000_ffffn);
  });
});

describe("AEAD", () => {
  const key = Buffer.alloc(32, 7);

  it("round-trips AES-256-GCM", () => {
    const plain = Buffer.from("hello raknet");
    const { ciphertext, tag } = aeadSeal(key, "aes-256-gcm", plain, COUNTER_BASE);
    expect(aeadOpen(key, "aes-256-gcm", ciphertext, tag, COUNTER_BASE).toString()).toBe(
      "hello raknet"
    );
  });

  it("round-trips ChaCha20-Poly1305", () => {
    const plain = Buffer.from("hello raknet");
    const { ciphertext, tag } = aeadSeal(key, "chacha20-poly1305", plain, COUNTER_BASE);
    expect(aeadOpen(key, "chacha20-poly1305", ciphertext, tag, COUNTER_BASE).toString()).toBe(
      "hello raknet"
    );
  });

  it("rejects a tampered tag", () => {
    const { ciphertext, tag } = aeadSeal(key, "aes-256-gcm", Buffer.from("x"), COUNTER_BASE);
    tag[0] ^= 0xff;
    expect(() => aeadOpen(key, "aes-256-gcm", ciphertext, tag, COUNTER_BASE)).toThrow();
  });

  it("rejects the wrong counter", () => {
    const { ciphertext, tag } = aeadSeal(key, "aes-256-gcm", Buffer.from("x"), COUNTER_BASE);
    expect(() => aeadOpen(key, "aes-256-gcm", ciphertext, tag, COUNTER_BASE + 1n)).toThrow();
  });
});

describe("RakNet datagrams", () => {
  it("parses a reliable-ordered data datagram", () => {
    const dg = parseDatagram(hex(DATAGRAM));
    expect(dg.type).toBe("data");
    expect(dg.datagramNumber).toBe(0x010203);
    expect(dg.messages).toHaveLength(1);
    expect(dg.messages[0].reliability).toBe(RELIABILITY.RELIABLE_ORDERED);
    expect(dg.messages[0].messageNumber).toBe(0x0a0b0c);
    expect(dg.messages[0].orderIndex).toBe(0x112233);
    expect(dg.messages[0].orderChannel).toBe(5);
    expect(dg.messages[0].payload.toString("hex")).toBe("aa");
  });

  it("rebuilds the exact measured bytes", () => {
    const dg = parseDatagram(hex(DATAGRAM));
    expect(buildDatagram(dg).toString("hex")).toBe(DATAGRAM);
  });

  it("parses ACK ranges", () => {
    const dg = parseDatagram(hex(ACK));
    expect(dg.type).toBe("ack");
    expect(dg.ackRanges).toEqual([
      { min: 1, max: 1 },
      { min: 5, max: 9 },
    ]);
    expect(buildDatagram(dg).toString("hex")).toBe(ACK);
  });

  it("parses NAK ranges", () => {
    const dg = parseDatagram(hex(NAK));
    expect(dg.type).toBe("nak");
    expect(dg.ackRanges).toEqual([{ min: 2, max: 2 }]);
    expect(buildDatagram(dg).toString("hex")).toBe(NAK);
  });

  it("parses a split message header", () => {
    const dg = parseDatagram(hex("80" + "000000" + SPLITMSG));
    const m = dg.messages[0];
    expect(m.reliability).toBe(RELIABILITY.RELIABLE);
    expect(m.split).toBe(true);
    expect(m.splitCount).toBe(3);
    expect(m.splitId).toBe(0x1234);
    expect(m.splitIndex).toBe(1);
    expect(m.messageNumber).toBe(0x050607);
    expect(m.payload.toString()).toBe("abcd");
  });

  it("builds a message with the same field order", () => {
    const buf = buildMessage({
      reliability: RELIABILITY.RELIABLE,
      split: true,
      payload: Buffer.from("abcd"),
      messageNumber: 0x050607,
      splitCount: 3,
      splitId: 0x1234,
      splitIndex: 1,
    });
    expect(buf.toString("hex")).toBe(SPLITMSG);
  });
});

describe("split reassembly", () => {
  it("returns the payload once every part arrived", () => {
    const asm = new SplitAssembler();
    const parts = [Buffer.from("ab"), Buffer.from("cd"), Buffer.from("ef")];
    const outs = [];
    for (let i = 0; i < parts.length; i++) {
      const out = asm.add({
        split: true,
        splitCount: 3,
        splitId: 7,
        splitIndex: i,
        payload: parts[i],
      });
      if (out) outs.push(out);
    }
    expect(outs).toHaveLength(1);
    expect(outs[0].toString()).toBe("abcdef");
  });

  it("keeps parts of different split ids apart", () => {
    const asm = new SplitAssembler();
    expect(
      asm.add({ split: true, splitCount: 2, splitId: 1, splitIndex: 0, payload: Buffer.from("a") })
    ).toBeNull();
    expect(
      asm.add({ split: true, splitCount: 2, splitId: 2, splitIndex: 0, payload: Buffer.from("b") })
    ).toBeNull();
  });
});

describe("offline messages", () => {
  it("builds an unconnected ping with the RakNet magic", () => {
    const buf = buildUnconnectedPing(0x1122334455667788n, 0x0102030405060708n);
    expect(buf.toString("hex")).toBe(PING);
    expect(buf.subarray(1, 17)).toEqual(OFFLINE_MAGIC);
  });

  it("parses an unconnected pong", () => {
    const pong = parseUnconnectedPong(hex(PONG));
    expect(pong.time).toBe(0x1122334455667788n);
    expect(pong.serverGuid).toBe(0xaabbccddeeff0011n);
    expect(pong.motd).toBe("MOTD");
  });
});
